<div class="card"><div class="card-header"><h5 class="mb-0">Tunggakan Tahun Sebelumnya</h5></div><div class="card-body"><div class="row g-2"><div class="col-md-5"><select id="periode" class="form-select"><option value="">Pilih Tahun Berjalan</option><?php foreach($periode as $p): ?><option value="<?= $p['id'] ?>" <?= $p['status']==='Aktif'?'selected':'' ?>><?= html_escape($p['periode']) ?></option><?php endforeach ?></select></div><div class="col-md-5"><select id="kelas" class="form-select"><option value="">Semua Kelas Saat Ini</option><?php foreach($kelas as $k): ?><option value="<?= $k['id'] ?>"><?= html_escape($k['nama_kelas']) ?></option><?php endforeach ?></select></div><div class="col-md-2 d-grid"><button id="tampil" class="btn btn-primary">Tampilkan</button></div></div></div></div>
<div class="card"><div class="card-header d-flex justify-content-between"><h5 class="mb-0">Daftar Tunggakan Lama</h5><button onclick="window.print()" class="btn btn-secondary no-print">Cetak Daftar</button></div><div class="card-body"><div class="table-responsive"><table class="table align-middle"><thead><tr><th>Siswa</th><th>Kelas Saat Ini</th><th>Tahun Asal</th><th>Rincian</th><th class="text-end">Total Tunggakan</th><th>Aksi</th></tr></thead><tbody id="data"><tr><td colspan="6" class="empty-state">Pilih tahun berjalan.</td></tr></tbody></table></div></div></div>
<div class="modal fade" id="modalDetail"><div class="modal-dialog modal-xl"><div class="modal-content"><div class="modal-header"><h5 class="modal-title">Rincian Tunggakan</h5><button class="btn-close" data-bs-dismiss="modal"></button></div><div class="modal-body" id="detail"></div></div></div></div>
<script>$(function(){const money=n=>'Rp'+Number(n||0).toLocaleString('id-ID');function load(){if(!$('#periode').val())return;$.post('<?= base_url('admin/tunggakan/tunggakan_lama/result') ?>',{id_periode_berjalan:$('#periode').val(),id_kelas_setting:$('#kelas').val()},r=>$('#data').html(r.length?r.map(x=>`<tr><td><strong>${escapeHtml(x.nama_siswa)}</strong><br><small>${escapeHtml(x.nis)}</small></td><td>${escapeHtml(x.kelas_saat_ini||'-')}</td><td>${escapeHtml(x.tahun_asal)}</td><td>${x.jumlah_tagihan} tagihan</td><td class="text-end fw-semibold text-danger">${money(x.total_tunggakan)}</td><td><div class="action-buttons"><button class="btn btn-sm btn-primary detail" data-id="${x.id_siswa}" data-period="${x.id_periode}">Detail</button><a class="btn btn-sm btn-warning" href="<?= base_url('admin/tunggakan/surat_tunggakan') ?>?siswa=${x.id_siswa}">Buat Surat</a></div></td></tr>`).join(''):'<tr><td colspan="6" class="empty-state">Tidak ada tunggakan tahun sebelumnya.</td></tr>'),'json')}$('#tampil').click(load);$(document).on('click','.detail',function(){$.post('<?= base_url('admin/tunggakan/tunggakan_lama/detail') ?>',{id_siswa:$(this).data('id'),id_periode:$(this).data('period')},r=>{$('#detail').html('<table class="table"><thead><tr><th>Tagihan</th><th>Periode</th><th class="text-end">Nominal</th><th class="text-end">Dibayar</th><th class="text-end">Sisa</th></tr></thead><tbody>'+r.filter(x=>Number(x.sisa_tagihan)>0&&x.dianggap_tunggakan==='Ya').map(x=>`<tr><td>${escapeHtml(x.nama_tagihan)}</td><td>${escapeHtml((x.nama_bulan||'')+' '+x.tahun)}</td><td class="text-end">${money(x.nominal_tagihan)}</td><td class="text-end">${money(x.nominal_dibayar)}</td><td class="text-end">${money(x.sisa_tagihan)}</td></tr>`).join('')+'</tbody></table>');bootstrap.Modal.getOrCreateInstance(document.getElementById('modalDetail')).show()},'json')});load()});</script>
